// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/floors/{floor}/elevators", wrapper.GetVisibleElevators)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/floors/{floor}/hall-calls", wrapper.ListFloorHallCalls)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/floors/{floor}/hall-calls", wrapper.PressHallButton)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/elevators", wrapper.ListElevators)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/elevators", wrapper.CreateElevator)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/elevators/{elevatorId}", wrapper.GetElevator)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/elevators/{elevatorId}", wrapper.PatchElevator)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/elevators/{elevatorId}/car-calls", wrapper.PressCarButton)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/elevators/{elevatorId}/doors/open", wrapper.OpenDoor)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/elevators/{elevatorId}/doors/close", wrapper.CloseDoor)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/elevators/{elevatorId}/stop", wrapper.StopElevator)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/elevators/{elevatorId}/resume", wrapper.ResumeElevator)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/hall-calls", wrapper.ListHallCalls)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/hall-calls/{callId}", wrapper.CancelHallCall)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/simulation/tick", wrapper.AdvanceTick)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/simulation/reset", wrapper.ResetSimulation)
	})

	return r
}

